"""Generates app/glossary/terms.json from a compact table (kept in-repo for reviewability)."""
import json, pathlib, re

SRC = "General educational description written for MedLens (synthetic-data hackathon project), based on standard lab-medicine terminology. Not patient-specific."
T = []
def add(term, aliases, cat, expl, not_=None, possibilities=None):
    tid = re.sub(r"[^a-z0-9]+", "_", term.lower()).strip("_")
    e = {"id": tid, "term": term, "aliases": aliases, "category": cat, "plain_explanation": expl, "source_note": SRC}
    if not_: e["what_it_is_not"] = not_
    if possibilities: e["possibilities"] = possibilities
    T.append(e)

H = "Blood count (CBC)"
add("Complete Blood Count", ["CBC", "Hemogram", "Haemogram", "Complete Haemogram", "Full Blood Count", "FBC"], H, "A group of tests that counts and measures the different cells in your blood: red cells, white cells and platelets.")
add("Hemoglobin", ["Haemoglobin", "Hb", "Hgb"], H, "A protein inside red blood cells that carries oxygen from the lungs to the rest of the body. This test measures how much of it is in your blood.")
add("Red Blood Cell Count", ["RBC", "RBC Count", "Red Blood Cells", "Total RBC Count", "Erythrocytes", "Erythrocyte Count"], H, "Counts the number of red blood cells, the cells that carry oxygen, in a small amount of blood.")
add("White Blood Cell Count", ["WBC", "WBC Count", "White Blood Cells", "Leukocytes", "Leucocytes", "Leukocyte Count"], H, "Counts the white blood cells, which are part of the body's defence (immune) system.")
add("Total Leukocyte Count", ["TLC", "Total Leucocyte Count", "Total WBC Count"], H, "Another name for the total white blood cell count: the number of all immune-system white cells in a sample of blood.")
add("Differential Leukocyte Count", ["DLC", "Differential Count", "Differential Leucocyte Count"], H, "Breaks the white blood cells into their five main types and shows what share (percentage) each type makes up.")
add("Platelet Count", ["Platelets", "PLT", "Thrombocytes", "Platelet"], H, "Counts platelets, tiny cell fragments that help blood clot and stop bleeding.")
add("Packed Cell Volume", ["Haematocrit", "Hematocrit", "HCT", "Hct"], H, "The share of your blood volume that is made up of red blood cells, shown as a percentage.")
add("PCV", ["PCV"], "Ambiguous abbreviation", "PCV is an abbreviation with more than one meaning. In a blood-count report it usually means Packed Cell Volume (the share of blood made of red cells). Ask the lab if you are unsure.",
    possibilities=[{"meaning": "Packed Cell Volume (haematocrit) — share of blood made of red cells", "context_keywords": ["hemoglobin", "haemoglobin", "cbc", "hemogram", "haemogram", "rbc", "mcv", "blood count"]},
                   {"meaning": "Pneumococcal Conjugate Vaccine — a vaccine name", "context_keywords": ["vaccine", "vaccination", "immunization", "immunisation", "dose"]}])
add("Mean Corpuscular Volume", ["MCV"], H, "The average size of your red blood cells.")
add("Mean Corpuscular Hemoglobin", ["MCH", "Mean Corpuscular Haemoglobin"], H, "The average amount of hemoglobin inside one red blood cell.")
add("Mean Corpuscular Hemoglobin Concentration", ["MCHC", "Mean Corpuscular Haemoglobin Concentration"], H, "The average concentration of hemoglobin in a given volume of red blood cells.")
add("Red Cell Distribution Width", ["RDW", "RDW-CV", "RDW-SD", "RDW CV", "RDW SD"], H, "Shows how much your red blood cells vary in size from one another.")
add("Neutrophils", ["Neutrophil", "Polymorphs", "Segmented Neutrophils", "Neutrophil Count"], H, "The most common type of white blood cell. The report shows their share of all white cells or their count.")
add("Lymphocytes", ["Lymphocyte", "Lymphs", "Lymphocyte Count"], H, "A type of white blood cell that includes B cells and T cells, part of the immune system.")
add("Eosinophils", ["Eosinophil", "Eosinophil Count", "Absolute Eosinophil Count", "AEC"], H, "A type of white blood cell. The report shows their share of all white cells or their count.")
add("Monocytes", ["Monocyte", "Monocyte Count"], H, "A type of white blood cell that can move into tissues. The report shows their share or count.")
add("Basophils", ["Basophil", "Basophil Count"], H, "The least common type of white blood cell. The report shows their share or count.")
add("Erythrocyte Sedimentation Rate", ["ESR", "Sed Rate", "Sedimentation Rate"], H, "Measures how fast red blood cells settle to the bottom of a thin tube in one hour.", "It is a general measurement and does not point to any one specific condition.")
add("Mean Platelet Volume", ["MPV"], H, "The average size of your platelets.")
add("Reticulocyte Count", ["Reticulocytes", "Retic Count"], H, "Counts young, newly made red blood cells.")
add("Peripheral Smear", ["Peripheral Blood Smear", "PBS", "Blood Smear"], H, "A drop of blood spread on a glass slide and looked at under a microscope to describe the shape and look of blood cells.")

L = "Lipid profile"
add("Lipid Profile", ["Lipid Panel", "Lipid Test"], L, "A group of tests that measures fats (lipids) such as cholesterol and triglycerides in the blood.")
add("Total Cholesterol", ["Cholesterol Total", "Serum Cholesterol", "Cholesterol, Total", "Cholesterol"], L, "Measures the total amount of cholesterol, a waxy fat-like substance, carried in your blood.")
add("LDL Cholesterol", ["LDL", "LDL-C", "Low Density Lipoprotein", "LDL Cholesterol Direct", "LDL-Cholesterol"], L, "Measures cholesterol carried by low-density lipoproteins, one of the particles that move cholesterol through the blood.")
add("HDL Cholesterol", ["HDL", "HDL-C", "High Density Lipoprotein", "HDL-Cholesterol"], L, "Measures cholesterol carried by high-density lipoproteins, particles that carry cholesterol back to the liver.")
add("VLDL Cholesterol", ["VLDL", "Very Low Density Lipoprotein", "VLDL-Cholesterol"], L, "Measures cholesterol carried by very-low-density lipoproteins, particles that also carry triglycerides. Often calculated rather than measured.")
add("Triglycerides", ["Triglyceride", "TG", "TGL", "Serum Triglycerides"], L, "Measures triglycerides, a common type of fat in the blood that the body uses for energy.")
add("Non-HDL Cholesterol", ["Non HDL Cholesterol", "Non-HDL"], L, "Total cholesterol minus HDL cholesterol; a calculated number.")
add("Cholesterol/HDL Ratio", ["Total Cholesterol/HDL Ratio", "TC/HDL Ratio", "Chol/HDL Ratio"], L, "A calculated ratio that divides total cholesterol by HDL cholesterol.")
add("LDL/HDL Ratio", ["LDL HDL Ratio"], L, "A calculated ratio that divides LDL cholesterol by HDL cholesterol.")

LF = "Liver function (LFT)"
add("Liver Function Test", ["LFT", "Liver Function Tests", "Liver Panel"], LF, "A group of blood tests that measure substances made or processed by the liver.")
add("Alanine Aminotransferase", ["ALT", "SGPT", "ALT (SGPT)", "SGPT (ALT)", "Alanine Transaminase"], LF, "Measures ALT, an enzyme found mostly in liver cells. SGPT is an older name for the same test.")
add("Aspartate Aminotransferase", ["AST", "SGOT", "AST (SGOT)", "SGOT (AST)", "Aspartate Transaminase"], LF, "Measures AST, an enzyme found in the liver, heart and muscles. SGOT is an older name for the same test.")
add("Alkaline Phosphatase", ["ALP", "Alk Phos", "Serum Alkaline Phosphatase"], LF, "Measures ALP, an enzyme found in the liver, bile ducts and bones.")
add("Total Bilirubin", ["Bilirubin Total", "Bilirubin, Total", "Bilirubin (Total)", "Serum Bilirubin Total", "T. Bilirubin"], LF, "Measures all bilirubin in the blood. Bilirubin is a yellow substance made when old red blood cells are broken down.")
add("Direct Bilirubin", ["Bilirubin Direct", "Bilirubin, Direct", "Bilirubin (Direct)", "Conjugated Bilirubin", "D. Bilirubin"], LF, "Measures the part of bilirubin that the liver has already processed (conjugated).")
add("Indirect Bilirubin", ["Bilirubin Indirect", "Bilirubin, Indirect", "Bilirubin (Indirect)", "Unconjugated Bilirubin", "I. Bilirubin"], LF, "The part of bilirubin not yet processed by the liver; usually calculated as total minus direct bilirubin.")
add("Bilirubin", ["Serum Bilirubin"], LF, "A yellow substance made when old red blood cells are broken down; the liver processes it so it can leave the body.")
add("Albumin", ["Serum Albumin", "ALB"], LF, "Measures albumin, the main protein made by the liver; it helps keep fluid inside blood vessels.")
add("Globulin", ["Serum Globulin", "Globulins"], LF, "Measures globulins, a group of blood proteins that includes antibodies. Often calculated as total protein minus albumin.")
add("Total Protein", ["Serum Total Protein", "Protein Total", "Total Proteins"], LF, "Measures the total amount of protein (albumin plus globulins) in the blood.")
add("A/G Ratio", ["Albumin/Globulin Ratio", "A:G Ratio", "AG Ratio", "Albumin Globulin Ratio"], LF, "A calculated number that divides albumin by globulin.")
add("Gamma-Glutamyl Transferase", ["GGT", "GGTP", "Gamma GT", "Gamma Glutamyl Transferase"], LF, "Measures GGT, an enzyme found mainly in the liver and bile ducts.")

K = "Kidney function (KFT/RFT)"
add("Kidney Function Test", ["KFT", "RFT", "Renal Function Test", "Renal Profile"], K, "A group of blood tests that measure waste products and salts that the kidneys help control.")
add("Creatinine", ["Serum Creatinine", "S. Creatinine", "Creat"], K, "Measures creatinine, a waste product from normal muscle activity that the kidneys filter out of the blood.")
add("Blood Urea Nitrogen", ["BUN", "Urea Nitrogen"], K, "Measures the nitrogen part of urea, a waste product the kidneys remove from the blood.")
add("Urea", ["Blood Urea", "Serum Urea"], K, "Measures urea, a waste product made when the body breaks down protein; the kidneys remove it.")
add("Uric Acid", ["Serum Uric Acid", "S. Uric Acid"], K, "Measures uric acid, a waste product made when the body breaks down substances called purines.")
add("Estimated Glomerular Filtration Rate", ["eGFR", "GFR", "EGFR", "Estimated GFR"], K, "A calculated estimate of how much blood the kidneys filter each minute, based on creatinine, age and sex.", "It is an estimate from a formula, not a direct measurement.")
add("Sodium", ["Serum Sodium", "Na+", "S. Sodium"], "Electrolytes", "Measures sodium, a salt (electrolyte) that helps control fluid balance and nerve signals.")
add("Potassium", ["Serum Potassium", "K+", "S. Potassium"], "Electrolytes", "Measures potassium, an electrolyte important for muscles and heart rhythm.")
add("Chloride", ["Serum Chloride", "Cl-"], "Electrolytes", "Measures chloride, an electrolyte that works with sodium to balance body fluids.")
add("Bicarbonate", ["HCO3", "Serum Bicarbonate", "Total CO2"], "Electrolytes", "Measures bicarbonate, which helps keep the blood's acid-base balance steady.")
add("Calcium", ["Serum Calcium", "Total Calcium"], "Electrolytes", "Measures calcium in the blood, a mineral used by bones, muscles and nerves.")
add("Phosphorus", ["Serum Phosphorus", "Phosphate", "Inorganic Phosphorus"], "Electrolytes", "Measures phosphorus, a mineral that works with calcium in bones and energy use.")
add("Electrolytes", ["Serum Electrolytes", "Electrolyte Panel"], "Electrolytes", "Salts and minerals in the blood, such as sodium, potassium and chloride, that carry an electric charge.")
add("BUN/Creatinine Ratio", ["BUN Creatinine Ratio", "Urea/Creatinine Ratio"], K, "A calculated ratio comparing blood urea nitrogen with creatinine.")

D = "Diabetes / glucose"
add("Fasting Blood Sugar", ["FBS", "Fasting Glucose", "Fasting Blood Glucose", "Glucose Fasting", "Glucose, Fasting", "Fasting Plasma Glucose", "FPG", "Blood Sugar Fasting", "Plasma Glucose Fasting"], D, "Measures the sugar (glucose) level in blood after not eating for a set time, usually 8–12 hours.")
add("Post Prandial Blood Sugar", ["PPBS", "PP Blood Sugar", "Post Prandial Glucose", "Glucose Post Prandial", "Glucose, Post Prandial", "PPBG", "Blood Sugar PP", "Postprandial Glucose", "Plasma Glucose PP"], D, "Measures blood sugar (glucose) at a set time, usually 2 hours, after a meal.")
add("Random Blood Sugar", ["RBS", "Random Glucose", "Glucose Random", "Random Plasma Glucose"], D, "Measures blood sugar (glucose) at any time, without fasting.")
add("Glucose", ["Blood Glucose", "Blood Sugar", "Plasma Glucose"], D, "Glucose is the main sugar in the blood and the body's main source of energy.")
