add("Thyroid Stimulating Hormone", ["TSH", "Thyrotropin", "TSH Ultrasensitive", "Ultrasensitive TSH"], TH, "Measures TSH, a hormone made by the pituitary gland in the brain that tells the thyroid gland how much hormone to make.")
add("Triiodothyronine", ["T3", "Total T3", "T3 Total"], TH, "Measures T3, one of the two main hormones made by the thyroid gland.")
add("Thyroxine", ["T4", "Total T4", "T4 Total"], TH, "Measures T4, the main hormone made by the thyroid gland.")
add("Free T3", ["FT3", "Free Triiodothyronine"], TH, "Measures the 'free' part of T3 that is not attached to proteins in the blood.")
add("Free T4", ["FT4", "Free Thyroxine"], TH, "Measures the 'free' part of T4 that is not attached to proteins in the blood.")
add("Anti-TPO Antibodies", ["Anti TPO", "Anti-TPO", "TPO Antibodies", "Thyroid Peroxidase Antibodies"], TH, "Measures antibodies against thyroid peroxidase, an enzyme in the thyroid gland.")

